class TwoSlotDailyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity(
            "SPY", Resolution.Daily, fillDataForward=False
        ).Symbol
        self.aapl = self.AddEquity(
            "AAPL", Resolution.Daily, fillDataForward=False
        ).Symbol
        self.ibm = self.AddEquity(
            "IBM", Resolution.Daily, fillDataForward=False
        ).Symbol
        self.bac = self.AddEquity(
            "BAC", Resolution.Daily, fillDataForward=False
        ).Symbol
        self.aig = self.AddEquity(
            "AIG", Resolution.Daily, fillDataForward=False
        ).Symbol

        self.required_symbols = [
            self.spy,
            self.aapl,
            self.ibm,
            self.bac,
            self.aig
        ]

        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(100, Resolution.Daily)

        self.previous_spy_close = None
        self.previous_spy_sma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def OnData(self, data):
        bars = {}

        for symbol in self.required_symbols:
            if data.Bars.ContainsKey(symbol):
                bar = data.Bars[symbol]
                if bar is not None:
                    bars[symbol] = bar

        spy_crossed_above, spy_crossed_below = self.UpdateMarketState(bars)

        if self.IsWarmingUp:
            return

        if len(bars) != len(self.required_symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        if self.previous_spy_close is None or self.previous_spy_sma is None:
            return

        spy_close = float(bars[self.spy].Close)
        aapl_close = float(bars[self.aapl].Close)

        # Evaluate sells before buys.
        if self.strategy_a_lot > 0 and spy_crossed_below:
            self.MarketOrder(self.spy, -self.strategy_a_lot)
            self.strategy_a_lot = 0

        if (
            self.strategy_b_lot > 0
            and float(self.aapl_rsi.Current.Value) > 60.0
        ):
            self.MarketOrder(self.aapl, -self.strategy_b_lot)
            self.strategy_b_lot = 0

        # Strategy A buy.
        if self.strategy_a_lot == 0 and spy_crossed_above:
            target_value = 0.40 * float(self.Portfolio.TotalPortfolioValue)
            quantity = math.floor(target_value / spy_close)

            if quantity > 0:
                self.MarketOrder(self.spy, quantity)
                self.strategy_a_lot = quantity

        # Strategy B buy.
        if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
            if float(self.Portfolio.Cash) >= 20000.0:
                quantity = math.floor(20000.0 / aapl_close)

                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_lot = quantity

    def UpdateMarketState(self, bars):
        spy_crossed_above = False
        spy_crossed_below = False

        if self.spy in bars:
            spy_close = float(bars[self.spy].Close)
            current_spy_sma = None

            if self.spy_sma.IsReady:
                current_spy_sma = float(self.spy_sma.Current.Value)

                if (
                    self.previous_spy_close is not None
                    and self.previous_spy_sma is not None
                ):
                    spy_crossed_above = (
                        self.previous_spy_close <= self.previous_spy_sma
                        and spy_close > current_spy_sma
                    )
                    spy_crossed_below = (
                        self.previous_spy_close >= self.previous_spy_sma
                        and spy_close < current_spy_sma
                    )

            self.previous_spy_close = spy_close

            if current_spy_sma is not None:
                self.previous_spy_sma = current_spy_sma

        if self.aapl in bars:
            aapl_close = float(bars[self.aapl].Close)

            if self.previous_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < self.previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

        return spy_crossed_above, spy_crossed_below

