class StrategySystem(QCAlgorithm):
    MA_PERIOD = 20
    RSI_PERIOD = 14
    RED_DAYS = 3
    AAPL_BUY_AMOUNT = 20000.0
    SPY_ALLOCATION = 0.40

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.spy = self.AddEquity("SPY", Resolution.Daily).Symbol
        self.aapl = self.AddEquity("AAPL", Resolution.Daily).Symbol
        self.ibm = self.AddEquity("IBM", Resolution.Daily).Symbol
        self.bac = self.AddEquity("BAC", Resolution.Daily).Symbol
        self.aig = self.AddEquity("AIG", Resolution.Daily).Symbol

        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.spy_ma = self.SMA(self.spy, self.MA_PERIOD, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            self.RSI_PERIOD,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.SetWarmUp(
            max(self.MA_PERIOD + 1, self.RSI_PERIOD + 1, self.RED_DAYS + 1),
            Resolution.Daily
        )

        self.previous_spy_close = None
        self.previous_spy_ma = None
        self.previous_aapl_close = None
        self.aapl_red_streak = 0
        self.aapl_close_count = 0

        self.lots = {
            "A": 0,
            "B": 0
        }

        self.pending_orders = {}

    def OnData(self, data):
        bars = data.Bars
        present = {symbol: bars.ContainsKey(symbol) for symbol in self.symbols}

        spy_bar = bars[self.spy] if present[self.spy] else None
        aapl_bar = bars[self.aapl] if present[self.aapl] else None

        prior_spy_close = self.previous_spy_close
        prior_spy_ma = self.previous_spy_ma
        prior_aapl_close = self.previous_aapl_close

        spy_close = None
        current_spy_ma = None
        current_aapl_rsi = None

        if spy_bar is not None:
            spy_close = float(spy_bar.Close)

            if self.spy_ma.IsReady:
                current_spy_ma = float(self.spy_ma.Current.Value)

            self.previous_spy_close = spy_close

            if current_spy_ma is not None:
                self.previous_spy_ma = current_spy_ma

        if aapl_bar is not None:
            aapl_close = float(aapl_bar.Close)
            self.aapl_close_count += 1

            if prior_aapl_close is None:
                self.aapl_red_streak = 0
            elif aapl_close < prior_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

            self.previous_aapl_close = aapl_close

            if self.aapl_rsi.IsReady:
                current_aapl_rsi = float(self.aapl_rsi.Current.Value)

        if not all(present.values()) or self.IsWarmingUp:
            return

        if (
            not self.spy_ma.IsReady
            or not self.aapl_rsi.IsReady
            or prior_spy_close is None
            or prior_spy_ma is None
            or current_spy_ma is None
            or spy_close is None
            or aapl_bar is None
            or current_aapl_rsi is None
        ):
            return

        spy_cross_above = (
            prior_spy_close <= prior_spy_ma
            and spy_close > current_spy_ma
        )

        spy_cross_below = (
            prior_spy_close >= prior_spy_ma
            and spy_close < current_spy_ma
        )

        aapl_red_three_days = self.aapl_red_streak >= self.RED_DAYS
        aapl_rsi_above_60 = current_aapl_rsi > 60.0

        if self.lots["A"] > 0 and not self._has_pending_order("A"):
            if spy_cross_below:
                self._submit_order(
                    "A",
                    self.spy,
                    -self.lots["A"],
                    "sell"
                )

        if self.lots["B"] > 0 and not self._has_pending_order("B"):
            if aapl_rsi_above_60:
                self._submit_order(
                    "B",
                    self.aapl,
                    -self.lots["B"],
                    "sell"
                )

        if self.lots["A"] == 0 and not self._has_pending_order("A"):
            if spy_cross_above:
                target_value = (
                    float(self.Portfolio.TotalPortfolioValue)
                    * self.SPY_ALLOCATION
                )
                shares = int(floor(target_value / spy_close))

                if shares > 0:
                    self._submit_order("A", self.spy, shares, "buy")

        if self.lots["B"] == 0 and not self._has_pending_order("B"):
            if aapl_red_three_days:
                available_cash = float(self.Portfolio.Cash)

                if available_cash >= self.AAPL_BUY_AMOUNT:
                    shares = int(floor(self.AAPL_BUY_AMOUNT / float(aapl_bar.Close)))

                    if shares > 0:
                        self._submit_order("B", self.aapl, shares, "buy")

    def _has_pending_order(self, strategy):
        return any(
            order_strategy == strategy
            for order_strategy, _ in self.pending_orders.values()
        )

    def _submit_order(self, strategy, symbol, quantity, side):
        if quantity == 0 or self._has_pending_order(strategy):
            return

        ticket = self.MarketOrder(
            symbol,
            quantity,
            False,
            "{}_{}".format(strategy, side)
        )

        if ticket is not None:
            self.pending_orders[int(ticket.OrderId)] = (strategy, side)

    def OnOrderEvent(self, orderEvent):
        order_id = int(orderEvent.OrderId)

        if order_id not in self.pending_orders:
            return

        strategy, side = self.pending_orders[order_id]
        fill_quantity = int(orderEvent.FillQuantity)

        if fill_quantity != 0:
            if side == "buy":
                self.lots[strategy] += fill_quantity
            else:
                self.lots[strategy] = max(
                    0,
                    self.lots[strategy] + fill_quantity
                )

        if orderEvent.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        ):
            del self.pending_orders[order_id]

